//! STD-8: the shapes of the C++ static initialisers ported table-driven ([`crate::static_inits`], generated by
//! `tools/native/static_inits.py`), and the few initialisers of other shapes, as phase B natives.
//!
//! The CRT runs these before `WinMain` with the process's initial x87 control word (`_CW_DEFAULT` 0x027F:
//! 53-bit precision, round to nearest; the game switches to 24 bits later, through Direct3D). With f32 operands
//! one x87 operation at 53 bits and the `fstp m32` that follows round exactly like the f64 operation and the
//! f64 → f32 conversion used here (the products of two f32 are exact in 53 bits).
//!
//! Every constructor, `atexit` and the `eh vector constructor iterator` are called through `orig!`'s address
//! registry (sa-game serves the CRT ones), with the convention the initialiser uses. Not ported: 0x8339CA (the
//! CRT's security-cookie set-up: system time, process / thread ids, tick and performance counters XORed into
//! `__security_cookie`; nothing ported reads the cookie).

use crate::abi::NativeReg;
use crate::mem::GPtr;

fn f(a: u32) -> f64 {
    GPtr::<f32>::from_addr(a as usize).read() as f64
}
fn put(d: u32, v: f64) {
    GPtr::<f32>::from_addr(d as usize).write(v as f32)
}
fn w32(a: u32, v: u32) {
    GPtr::<u32>::from_addr(a as usize).write(v)
}

/// The registered native entry at `addr` (phase B, 32-bit x86), else a "not ported" panic as `orig!` gives.
#[cfg(all(target_arch = "x86", not(sa_phase_a)))]
fn entry_at(addr: u32) -> usize {
    match crate::orig::registry::lookup(addr as usize) {
        Some(e) => e.entry,
        None => panic!(
            "static initialiser callee is not ported; phases B/C have no original code to call ({addr:#x} {})",
            crate::orig::registry::describe(addr as usize)
        ),
    }
}

/// `this->ctor()` (thiscall, no stack arguments); the result is ignored.
#[allow(unsafe_code)]
fn call_thiscall0(ctor: u32, this: u32) {
    #[cfg(all(target_arch = "x86", not(sa_phase_a)))]
    {
        // SAFETY: a registered thiscall entry of a constructor without stack arguments.
        let f =
            unsafe { core::mem::transmute::<usize, extern "thiscall-unwind" fn(u32) -> u32>(entry_at(ctor)) };
        f(this);
    }
    #[cfg(not(all(target_arch = "x86", not(sa_phase_a))))]
    let _ = (ctor, this);
}

/// CRT `atexit(fn)` (0x821D1E, cdecl).
#[allow(unsafe_code)]
fn atexit(dtor: u32) {
    #[cfg(all(target_arch = "x86", not(sa_phase_a)))]
    {
        // SAFETY: the CRT `atexit` entry sa-game registers (cdecl, one argument).
        let f =
            unsafe { core::mem::transmute::<usize, extern "C-unwind" fn(u32) -> i32>(entry_at(0x821D1E)) };
        f(dtor);
    }
    #[cfg(not(all(target_arch = "x86", not(sa_phase_a))))]
    let _ = dtor;
}

/// CRT `eh vector constructor iterator(ptr, size, count, ctor, dtor)` (0x821D30, stdcall).
#[allow(unsafe_code)]
fn vec_ctor(ptr: u32, size: u32, count: u32, ctor: u32, dtor: u32) {
    #[cfg(all(target_arch = "x86", not(sa_phase_a)))]
    {
        // SAFETY: the CRT vector constructor entry sa-game registers (stdcall, five arguments).
        let f = unsafe {
            core::mem::transmute::<usize, extern "stdcall-unwind" fn(u32, u32, u32, u32, u32)>(entry_at(
                0x821D30,
            ))
        };
        f(ptr, size, count, ctor, dtor);
    }
    #[cfg(not(all(target_arch = "x86", not(sa_phase_a))))]
    let _ = (ptr, size, count, ctor, dtor);
}

/// `fld [A]; fdiv [B]; fstp [D]`
pub extern "C-unwind" fn fdiv<const D: u32, const A: u32, const B: u32>() {
    put(D, f(A) / f(B));
}
/// `fld [A]; fmul [B]; fstp [D]`
pub extern "C-unwind" fn fmul<const D: u32, const A: u32, const B: u32>() {
    put(D, f(A) * f(B));
}
/// `fld [A]; fsub [B]; fstp [D]`
pub extern "C-unwind" fn fsub<const D: u32, const A: u32, const B: u32>() {
    put(D, f(A) - f(B));
}
/// `fld [A]; fmul [B]; fdivr [C]; fstp [D]`: `C / (A * B)`
pub extern "C-unwind" fn frecip_mul<const D: u32, const A: u32, const B: u32, const C: u32>() {
    put(D, f(C) / (f(A) * f(B)));
}
/// `fild [I]; fmul [A]; fmul [B]; call _ftol; mov [D], eax`: the low dword of the truncated 64-bit integer.
pub extern "C-unwind" fn ftol_mul<const D: u32, const I: u32, const A: u32, const B: u32>() {
    let i = GPtr::<i32>::from_addr(I as usize).read() as f64;
    let v = i * f(A) * f(B);
    w32(D, (v.trunc() as i64) as u32);
}
/// `mov eax, [S]; mov [D], eax`
pub extern "C-unwind" fn copy32<const D: u32, const S: u32>() {
    w32(D, GPtr::<u32>::from_addr(S as usize).read());
}
/// `mov ax, [S]; mov [D], ax`
pub extern "C-unwind" fn copy16<const D: u32, const S: u32>() {
    GPtr::<u16>::from_addr(D as usize).write(GPtr::<u16>::from_addr(S as usize).read());
}
/// `mov ecx, O; call C; push X; call atexit; pop ecx`
pub extern "C-unwind" fn ctor_atexit<const O: u32, const C: u32, const X: u32>() {
    call_thiscall0(C, O);
    atexit(X);
}
/// `mov ecx, O; jmp C`
pub extern "C-unwind" fn tail_ctor<const O: u32, const C: u32>() {
    call_thiscall0(C, O);
}
/// `push X; call atexit; pop ecx`
pub extern "C-unwind" fn atexit_only<const X: u32>() {
    atexit(X);
}
/// `eh vector constructor iterator(P, S, N, C, DT)`, then `atexit(X)`
pub extern "C-unwind" fn vec_ctor_atexit<
    const P: u32,
    const S: u32,
    const N: u32,
    const C: u32,
    const DT: u32,
    const X: u32,
>() {
    vec_ctor(P, S, N, C, DT);
    atexit(X);
}

/// The rows of [`crate::static_inits`]: `(address, name, shape<operands>)` → `NATIVES`.
macro_rules! static_inits {
    ($(($a:expr, $n:expr, $k:ident<$($x:literal),*>)),* $(,)?) => {
        /// The table-driven static initialisers (phase B natives).
        pub const NATIVES: &[crate::abi::NativeReg] = &[
            $(crate::abi::NativeReg { addr: $a, name: $n, entry: || $k::<$($x),*> as *const () as usize }),*
        ];
    };
}
pub(crate) use static_inits;

/// The hand-written initialisers of other shapes. Empty: the five STD-4 natives (0x84A720, 0x84E2E0, 0x8508C0, 0x850910,
/// 0x855FD0) were dropped when WRITER-P's hooks for the same addresses landed (one registration per address).
pub const NATIVES_MISC: &[NativeReg] = &[];
